window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-117"]=[{"id":"set2-GsLtdJVl","fingerprint":"c4366ecd73852ac5","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Ce definește conceptul de prevenție primară în contextul afecțiunilor orale?","options":[{"id":"A","text":"Acțiunea de a opri progresul unei boli în stadiul incipient pentru a preveni complicațiile."},{"id":"B","text":"Totalitatea măsurilor adoptate după apariția complicațiilor unei afecțiuni dentare."},{"id":"C","text":"O ramură a medicinei dentare care se concentrează exclusiv pe tratamentul imediat al afecțiunilor diagnosticate precoce."},{"id":"D","text":"Măsurile preventive luate înainte de debutul unei boli pentru a elimina posibilitatea apariției acesteia."},{"id":"E","text":"Utilizarea radiografiilor pentru detectarea leziunilor carioase incipiente."}],"correct":["D"],"pages":[378],"source":"set-2"},{"id":"set2-HSEcvGo6","fingerprint":"de5f22121aff1bd7","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele acțiuni sunt considerate măsuri de prevenție primară?","options":[{"id":"A","text":"Aplicarea profesională topică a fluorului."},{"id":"B","text":"Sigilarea șanțurilor și fosetelor molarilor și premolarilor."},{"id":"C","text":"Oprirea progresului unei boli în stadiul incipient."},{"id":"D","text":"Utilizarea radiografiilor pentru detectarea leziunilor carioase incipiente."},{"id":"E","text":"Introducerea fluorului în sistemul public de aprovizionare cu apă."}],"correct":["A","B","E"],"pages":[378],"source":"set-2"},{"id":"set2-JmgZiyzA","fingerprint":"ba184dacbee7ffd8","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Conform școlii anglo-saxone, care dintre următoarele sunt considerate măsuri de prevenție specifice în cadrul prevenției primare?","options":[{"id":"A","text":"Educația oro-dentară."},{"id":"B","text":"Sigilările dentare."},{"id":"C","text":"Screening-ul periodic."},{"id":"D","text":"Fluorizarea sistemului public de apă potabilă."},{"id":"E","text":"Educația nutrițională."}],"correct":["B","D"],"pages":[378],"source":"set-2"},{"id":"set2-GlDfLHuR","fingerprint":"5e95c26052e412e9","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt măsurile impuse în cadrul prevenției primare conform școlii românești de stomatologie pediatrică?","options":[{"id":"A","text":"Tratamentul profilactic al suprafețelor dentare la pacienții cu risc crescut."},{"id":"B","text":"Controlul periodic la medicul stomatolog."},{"id":"C","text":"Igiena orală."},{"id":"D","text":"Fluorizarea."},{"id":"E","text":"Diagnosticul precoce prin metode radiografice."}],"correct":["B","C","D"],"pages":[378],"source":"set-2"},{"id":"set2-YjzlaLQZ","fingerprint":"d2bf331533c112e0","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Ce acțiune definește prevenția secundară și care este un exemplu relevant?","options":[{"id":"A","text":"Promovarea sănătății și a măsurilor de protecție specifice; un exemplu este educația nutrițională."},{"id":"B","text":"Oprirea progresului unei boli în stadiul incipient; un exemplu este utilizarea radiografiilor pentru detectarea leziunilor carioase incipiente."},{"id":"C","text":"Eliminarea posibilității de apariție a bolii; un exemplu este sigilarea șanțurilor și fosetelor."},{"id":"D","text":"Evitarea gustărilor cu conținut crescut de zaharoză; un exemplu este screening-ul periodic."},{"id":"E","text":"Aplicarea în perioada prepatogenă; un exemplu este fluorizarea apei potabile."}],"correct":["B"],"pages":[378],"source":"set-2"},{"id":"set2-idDNcVha","fingerprint":"09fb1843d483b1ef","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele reprezintă măsuri specifice ale prevenției secundare?","options":[{"id":"A","text":"Terapia endodontică."},{"id":"B","text":"Aplicarea restaurărilor preventive cu rășini (RPR)."},{"id":"C","text":"Ortodonția interceptivă."},{"id":"D","text":"Monitorizarea anomaliilor de dezvoltare dentare."},{"id":"E","text":"Înlocuirea structurilor dentare pierdute prin lucrări protetice."}],"correct":["B","C","D"],"pages":[379],"source":"set-2"},{"id":"set2-tqouECoC","fingerprint":"55911e7b9e97c9bc","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Ce măsuri sunt incluse în categoria prevenției terțiare?","options":[{"id":"A","text":"Coafajul pulpar."},{"id":"B","text":"Utilizarea radiografiilor pentru detectarea leziunilor carioase incipiente."},{"id":"C","text":"Restaurările preventive cu rășini (RPR)."},{"id":"D","text":"Terapia endodontică."},{"id":"E","text":"Extracțiile dentare."}],"correct":["A","D","E"],"pages":[379],"source":"set-2"},{"id":"set2-5VbaZdsg","fingerprint":"37c97e8f1081556e","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt obiectivele evaluării riscului carios?","options":[{"id":"A","text":"Detectarea pacienților cu risc carios mare."},{"id":"B","text":"Justificarea și monitorizarea tratamentului."},{"id":"C","text":"Stabilirea unor metode preventiv-terapeutice specifice."},{"id":"D","text":"Extensia preventivă pentru prevenirea leziunilor carioase secundare."},{"id":"E","text":"Promovarea reabilitării orale a pacienților."}],"correct":["A","B","C"],"pages":[379],"source":"set-2"},{"id":"set2-mf7ChDKc","fingerprint":"55b98bfb7684b5f7","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Care afirmație referitoare la evaluarea riscului carios este corectă?","options":[{"id":"A","text":"Are ca unic scop alegerea metodelor de tratament protetic."},{"id":"B","text":"Analizează exclusiv factorii de protecție, ignorând factorii de risc."},{"id":"C","text":"Este un element cheie în prevenire, ghidând clinicianul în alegerea strategiilor adecvate."},{"id":"D","text":"Riscul copilului de a dezvolta o boală dentară este considerat constant."},{"id":"E","text":"Se efectuează o singură dată, la prima vizită, pentru a stabili un risc neschimbat."}],"correct":["C"],"pages":[379],"source":"set-2"},{"id":"set2-XRjk0Ak-","fingerprint":"b9c042d2a80b3989","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Ce limitare importantă are periajul dentar în ceea ce privește controlul plăcii bacteriene?","options":[{"id":"A","text":"Este o procedură care poate fi realizată exclusiv în cabinetul stomatologic."},{"id":"B","text":"Nu îndepărtează în totalitate placa bacteriană din șanțuri, fosete sau de pe fețele proximale."},{"id":"C","text":"Nu poate împiedica apariția leziunilor carioase sub nicio formă."},{"id":"D","text":"Este cea mai puțin eficientă metodă de menținere a sănătății parodontale."},{"id":"E","text":"Reprezintă un mijloc strict chimic de îndepărtare a plăcii bacteriene."}],"correct":["B"],"pages":[379],"source":"set-2"},{"id":"set2-cCUF4lFL","fingerprint":"c10bfaf8f0095814","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt conceptele fundamentale ale stomatologiei preventive?","options":[{"id":"A","text":"Evaluarea riscului carios."},{"id":"B","text":"Îngrijirea profesională acordată de clinician."},{"id":"C","text":"Îngrijirea la domiciliu efectuată de pacient și părinți."},{"id":"D","text":"Terapia curativă a afecțiunilor deja instalate."},{"id":"E","text":"Realizarea de lucrări protetice complexe."}],"correct":["A","B","C"],"pages":[379],"source":"set-2"},{"id":"set2-LfYLX2_s","fingerprint":"927eee2dc479bf17","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Care este definiția prevenției secundare?","options":[{"id":"A","text":"Acțiunea ce oprește progresul unei boli în stadiul incipient și previne apariția complicațiilor."},{"id":"B","text":"Ansamblul măsurilor pentru reducerea sau limitarea tulburărilor deja instalate."},{"id":"C","text":"Promovarea reabilitării orale a pacienților cu afecțiuni avansate."},{"id":"D","text":"Totalitatea procedurilor de igienizare efectuate de către pacient la domiciliu."},{"id":"E","text":"Aplicarea unui tratament curativ asociat cu o abordare preventivă pentru a evita complicațiile."}],"correct":["A"],"pages":[379],"source":"set-2"},{"id":"set2-ijvQnhjT","fingerprint":"835ecd17dbe0eb95","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele afirmații referitoare la recomandările generale pentru periajul dentar la copii sunt corecte?","options":[{"id":"A","text":"Periajul dentar trebuie realizat o dată pe zi, de preferat dimineața."},{"id":"B","text":"Periuța de dinți trebuie schimbată la un interval de 3 luni."},{"id":"C","text":"Durata recomandată pentru un periaj corect este de 3-5 minute."},{"id":"D","text":"Pentru copiii cu vârsta peste 3 ani, se utilizează o cantitate de pastă de dinți cu fluor de mărimea unui “bob de orez”."},{"id":"E","text":"Cel mai important periaj al zilei este cel de după micul dejun, pentru a îndepărta resturile alimentare."}],"correct":["B","C"],"pages":[380],"source":"set-2"},{"id":"set2-nB7XyfUJ","fingerprint":"c53596189ccb9463","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Ce caracteristică distinctivă aparține tehnicii de periaj Fones, recomandată copiilor mici?","options":[{"id":"A","text":"Jumătatea distală a caninului este igienizată odată cu dinții din zona frontală."},{"id":"B","text":"Perii periuței sunt așezați într-un unghi de 45° față de axul lung al dinților."},{"id":"C","text":"Este recomandată copiilor cu dexteritate bună, cu vârsta de peste 8 ani."},{"id":"D","text":"Asigură igienizarea șanțului gingival prin forțarea perilor în sulcus."},{"id":"E","text":"Se realizează mișcări rotative cu o rază cât mai mare posibil, cu arcadele în contact."}],"correct":["E"],"pages":[380],"source":"set-2"},{"id":"set2-1BBvbitB","fingerprint":"2bf45e5cd2aeb451","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Conform recomandărilor privind igiena orală, care este rolul părinților în periajul dentar al copiilor?","options":[{"id":"A","text":"Părinții trebuie să inițieze periajul dentar odată cu erupția molarilor primi temporari."},{"id":"B","text":"Periuța de dinți electrică este contraindicată, fiind mai puțin eficientă decât cea clasică la copii."},{"id":"C","text":"Este responsabilitatea exclusivă a copilului să își însușească obiceiul de periaj de la erupția primului dinte."},{"id":"D","text":"După vârsta de 6 ani, copilul poate realiza periajul dentar fără a mai fi supravegheat."},{"id":"E","text":"Părinții trebuie să efectueze periajul dentar al copilului cel puțin până la vârsta de 6 ani."}],"correct":["E"],"pages":[380],"source":"set-2"},{"id":"set2-EuHnZ60k","fingerprint":"c81d23b649e24852","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect tehnica de periaj Bass?","options":[{"id":"A","text":"Mișcările efectuate sunt rotative, cu o rază cât mai mare posibil."},{"id":"B","text":"Presupune igienizarea jumătății distale a caninului împreună cu dinții din zona distală, iar a celei meziale împreună cu dinții din zona frontală."},{"id":"C","text":"Este cunoscută și sub denumirea de tehnică creviculară, deoarece asigură igiena la nivelul șanțului gingival."},{"id":"D","text":"Periuța este așezată într-un unghi de 90 de grade față de suprafețele dentare."},{"id":"E","text":"Este recomandată copiilor cu dexteritate minimă, în stadiul de dentație temporară."}],"correct":["B","C"],"pages":[380],"source":"set-2"},{"id":"set2-mRdrYXlK","fingerprint":"ed0e60a6f63379e3","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Ce tipuri de alimente sunt recomandate pentru a favoriza autocurățirea și a menține igiena nutrițională?","options":[{"id":"A","text":"Alimente bogate în zaharoză, precum napolitanele."},{"id":"B","text":"Brânzeturile și merele, deoarece ajută la autocurățire."},{"id":"C","text":"Alimente mai dure, care nu rămân atașate de suprafețele dentare."},{"id":"D","text":"Alimente moi și lipicioase, precum caramelele."},{"id":"E","text":"Orice tip de aliment, cu condiția efectuării unui periaj imediat după consum."}],"correct":["B","C"],"pages":[380],"source":"set-2"},{"id":"set2-chXnkSDd","fingerprint":"7ca5bab9b484f801","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Care este cantitatea de pastă de dinți cu fluor recomandată pentru un copil în vârstă de 2 ani?","options":[{"id":"A","text":"Cât un bob de orez."},{"id":"B","text":"O cantitate egală cu lungimea capului periuței."},{"id":"C","text":"O cantitate egală cu jumătate din dimensiunea capului periuței."},{"id":"D","text":"O cantitate cât mai mică, fluorul fiind contraindicat sub 3 ani."},{"id":"E","text":"Cât un bob de mazăre."}],"correct":["A"],"pages":[380],"source":"set-2"},{"id":"set2-KZDaVaiR","fingerprint":"bd6fd9704596c4e3","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt afirmațiile corecte referitoare la proprietățile și efectele clorhexidinei în igienizarea cavității orale?","options":[{"id":"A","text":"Acționează eficient asupra microorganismelor Gram-pozitive, S. mutans fiind deosebit de sensibil."},{"id":"B","text":"Majoritatea tulpinilor de lactobacili sunt afectate semnificativ de acțiunea sa."},{"id":"C","text":"Are o afinitate puternică pentru structurile orale, precum dinții și mucoasa orală."},{"id":"D","text":"Principalul său efect secundar este toxicitatea sistemică ridicată."},{"id":"E","text":"În combinație cu fluorul, prezintă un efect sinergic, prelungind suprimarea S. mutans."}],"correct":["A","C","E"],"pages":[381],"source":"set-2"},{"id":"set2-Qxk7H9CL","fingerprint":"069592ff9a6a3ca8","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Un părinte este instruit cu privire la utilizarea clătirilor orale cu clorhexidină pentru copilul său. Care dintre următoarele informații este corectă?","options":[{"id":"A","text":"Printre efectele secundare se numără modificarea de culoare a dinților și un gust amar."},{"id":"B","text":"Periajul dentar trebuie efectuat imediat înainte de clătirea cu clorhexidină pentru a maximiza eficacitatea."},{"id":"C","text":"Este tratamentul de elecție pentru fluorizarea sistemică la copiii cu risc carios crescut."},{"id":"D","text":"Utilizarea clătirilor este recomandată copiilor cu vârsta sub 6 ani pentru a preveni ingestia accidentală."},{"id":"E","text":"O clătire cu clorhexidină 0,2% elimină complet riscul de apariție a leziunilor carioase."}],"correct":["A"],"pages":[381],"source":"set-2"},{"id":"set2-tLIPrL92","fingerprint":"a74c576cc44726de","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Care este regimul intensiv profesional recomandat pentru aplicarea gelului de clorhexidină 1% la copiii cu risc crescut de apariție a leziunilor carioase?","options":[{"id":"A","text":"O aplicare de 5 minute, o dată pe zi, timp de 14 zile."},{"id":"B","text":"Clătiri zilnice cu o soluție de 0,2% timp de o lună."},{"id":"C","text":"O singură aplicare profesională de 15 minute la fiecare 6 luni."},{"id":"D","text":"Aplicări de 3 ori câte 5 minute, timp de 2 zile consecutive, în gutiere personalizate."},{"id":"E","text":"Aplicarea în combinație cu pasta de dinți pentru un efect sinergic."}],"correct":["D"],"pages":[381],"source":"set-2"},{"id":"set2-jWGzDuyA","fingerprint":"e5e82c6f11c078b2","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect mecanismul actual de acțiune al fluorului în prevenirea cariilor dentare?","options":[{"id":"A","text":"Prezența sa în fluidul din placa bacteriană în timpul unei provocări acide este esențială pentru a încetini dizolvarea smalțului."},{"id":"B","text":"Funcționează exclusiv prin reducerea populației bacteriene de S. mutans."},{"id":"C","text":"Aplicarea topică duce la formarea de cristale de fluorură de calciu pe suprafața dentară."},{"id":"D","text":"Acțiunea sa principală constă în încorporarea permanentă în cristalele de hidroxiapatită în timpul formării dinților."},{"id":"E","text":"Cristalele de fluorură de calciu acționează ca un sistem cu eliberare lentă a fluorurii, controlat de pH."}],"correct":["A","C","E"],"pages":[381],"source":"set-2"},{"id":"set2-RQDWXGTU","fingerprint":"092c016f266f556d","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Ce caracteristici descriu corect fluorizarea apei ca metodă de administrare a fluorului?","options":[{"id":"A","text":"Este o măsură nerecomandată de Organizația Mondială a Sănătății din cauza riscurilor."},{"id":"B","text":"Este o metodă complexă și costisitoare, recomandată doar pentru comunitățile mici."},{"id":"C","text":"Reprezintă o formă de administrare locală, cu acțiune directă asupra smalțului."},{"id":"D","text":"Implementarea sa nu necesită instalații de apă cu un standard tehnic ridicat."},{"id":"E","text":"Poate reduce incidența leziunilor carioase cu până la 40–50%."}],"correct":["E"],"pages":[381],"source":"set-2"},{"id":"set2-5wB9KNNt","fingerprint":"3aa2c9eb313411fe","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt afirmațiile corecte cu privire la administrarea sistemică a fluorului?","options":[{"id":"A","text":"Suplimentarea sistemică pre-eruptivă s-a dovedit universal eficientă în prevenirea cariilor."},{"id":"B","text":"Adăugarea de fluor în lapte sau sarea de masă reprezintă alternative la fluorizarea apei."},{"id":"C","text":"Administrarea tabletelor de fluor trebuie ajustată în funcție de vârstă și conținutul de fluor din apa potabilă."},{"id":"D","text":"Expunerea pe termen lung la apa fluorizată reduce numărul leziunilor carioase la copii și adulți."},{"id":"E","text":"Tabletele cu fluor se recomandă a fi administrate de la naștere până la vârsta de 12 ani a copilului."}],"correct":["B","C","D"],"pages":[382],"source":"set-2"},{"id":"set2-tJM0JO7W","fingerprint":"43862844a04afa98","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Ce caracterizează fluoroza dentară?","options":[{"id":"A","text":"Se manifestă clinic doar după erupția completă a dentiției de lapte."},{"id":"B","text":"Reprezintă un defect cantitativ al smalțului, afectând în principal grosimea acestuia."},{"id":"C","text":"Apare la un aport de fluor sub 40 µg F/kg/zi."},{"id":"D","text":"Este un defect calitativ al smalțului cauzat de aportul excesiv de fluor pe termen lung în perioada de formare a dinților."},{"id":"E","text":"Este cauzată în principal de aplicările topice profesionale de fluor."}],"correct":["D"],"pages":[382],"source":"set-2"},{"id":"set2-ygX9z5pY","fingerprint":"bcde95826a819f23","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt informațiile corecte referitoare la toxicitatea fluorului?","options":[{"id":"A","text":"Doza toxică acută este de 5 mg F/kg."},{"id":"B","text":"Greața, vărsăturile și paresteziile sunt simptome ale intoxicației acute."},{"id":"C","text":"Utilizarea corectă a pastelor de dinți cu fluor este principalul factor de risc pentru toxicitatea letală la copii."},{"id":"D","text":"O doză de fluor care depășește 15 mg/kg este considerată letală."},{"id":"E","text":"Doza prag pentru dezvoltarea fluorozei ușoare este de 5 mg F/kg."}],"correct":["A","B","D"],"pages":[382],"source":"set-2"},{"id":"set2-6GBj2wfe","fingerprint":"eee29fffdbfcc2d1","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Conform clasificării lui Dean, care sunt caracteristicile asociate cu gradele specifice de fluoroză?","options":[{"id":"A","text":"Fluoroza foarte ușoară (Gradul II) implică zone opace, cretoase, ce acoperă aproximativ 10-25% din suprafața dintelui."},{"id":"B","text":"Fluoroza ușoară (Gradul III) prezintă un aspect normal al smalțului, cu o suprafață netedă și translucidă."},{"id":"C","text":"Fluoroza incertă (Gradul I) se manifestă prin opacifiere a peste 50% din suprafața smalțului."},{"id":"D","text":"Fluoroza moderată (Gradul IV) se caracterizează prin smalț albicios, colorație maronie și eroziuni."},{"id":"E","text":"Fluoroza severă (Gradul V) afectează forma generală a dintelui și prezintă cavități și colorație maronie extinsă."}],"correct":["A","D","E"],"pages":[382],"source":"set-2"},{"id":"set2-6us-G4t0","fingerprint":"57e24b2e100b3ca7","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Care este principiul de bază în creșterea eficienței anticariogene a aplicărilor topice de fluor?","options":[{"id":"A","text":"Eliberarea rapidă a unei doze mari de fluor pentru a distruge imediat placa bacteriană."},{"id":"B","text":"Stimularea producției de salivă prin intermediul compușilor cu fluor pentru a neutraliza acizii."},{"id":"C","text":"Depunerea fluorului exclusiv în interiorul dentinei pentru a crește rezistența acesteia."},{"id":"D","text":"Asigurarea prezenței fluorului la interfața placă bacteriană/smalț pentru a controla dizolvarea și reprecipitarea mineralelor."},{"id":"E","text":"Aplicarea rară a preparatelor cu concentrație scăzută de fluor pentru a evita toxicitatea."}],"correct":["D"],"pages":[382],"source":"set-2"},{"id":"set2-Kpa14HSU","fingerprint":"1c0dd03a5173ec1d","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele descrieri corespunde unui grad specific din clasificarea lui Dean pentru fluoroză?","options":[{"id":"A","text":"Câteva puncte sau pete albe cu o ușoară modificare a translucidității smalțului sunt specifice fluorozei incerte (Gradul I)."},{"id":"B","text":"Un lizereu albicios de 1-2 mm la nivelul molarilor, acoperind 50% din suprafață, este caracteristic fluorozei foarte ușoare (Gradul II)."},{"id":"C","text":"Pete alb cretoase, extinse pe toate suprafețele, cu o opacifiere sub 50% din suprafața totală a smalțului, caracterizează fluoroza ușoară (Gradul III)."},{"id":"D","text":"Afectarea formei generale a dintelui cu cavități confluente și aspect tigrat este specifică fluorozei moderate (Gradul IV)."},{"id":"E","text":"Suprafața smalțului netedă, translucidă, de culoare alb-gălbuie, definește fluoroza incertă (Gradul I)."}],"correct":["A","C"],"pages":[382],"source":"set-2"},{"id":"set2-MFuUVOI9","fingerprint":"bfbf8faad7406457","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Care este cantitatea de pastă de dinți recomandată pentru un copil cu vârsta cuprinsă între 6 luni și 3 ani?","options":[{"id":"A","text":"De dimensiunea unui bob de mazăre"},{"id":"B","text":"De dimensiunea unui bob de orez"},{"id":"C","text":"Cât să acopere jumătate din capul periuței"},{"id":"D","text":"O cantitate de 0,5 ml"},{"id":"E","text":"O cantitate egală cu 30% din lungimea perilor"}],"correct":["B"],"pages":[383],"source":"set-2"},{"id":"set2-iopB6l9M","fingerprint":"017e301cc42ebfcb","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele afirmații referitoare la clătirile orale cu ape de gură cu fluor sunt corecte?","options":[{"id":"A","text":"Clătirea zilnică cu soluție de NaF 0,05% este considerată cea mai eficientă."},{"id":"B","text":"Utilizarea lor a fost reintrodusă în populațiile de copii cu activitate carioasă ridicată sau în creștere."},{"id":"C","text":"Procedeul de clătire a cavității orale poate reduce leziunile carioase cu 20-40%."},{"id":"D","text":"Sunt recomandate pentru utilizare la copiii de vârstă preșcolară datorită eficienței lor ridicate."},{"id":"E","text":"În cadrul programelor școlare se utilizau soluții de fluorură fosfat acidulată (APF)."}],"correct":["A","B","C"],"pages":[383],"source":"set-2"},{"id":"set2-l3qZu_zs","fingerprint":"9761c2013c6e93a1","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Ce caracteristici definitorii au lacurile cu fluor, cum ar fi Duraphat sau Bifluorid?","options":[{"id":"A","text":"Necesită aplicarea în gutiere individuale pentru a fi eficiente."},{"id":"B","text":"Aderă la suprafețele dentare pentru o perioadă scurtă, de câteva ore."},{"id":"C","text":"Eliberează fluorul rapid, în totalitate, la interfața cu placa bacteriană."},{"id":"D","text":"Conțin concentrații scăzute de fluor și sunt destinate aplicării zilnice la domiciliu."},{"id":"E","text":"Sunt ușor de aplicat și se recomandă utilizarea lor de două ori pe an pentru rezultate optime."}],"correct":["E"],"pages":[383],"source":"set-2"},{"id":"set2-T8x7msy5","fingerprint":"34ea8ae417daf9af","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele produse pe bază de fluor nu sunt recomandate la copiii de vârstă preșcolară din cauza riscului de înghițire?","options":[{"id":"A","text":"Pasta de dinți în cantitate de dimensiunea unui bob de orez."},{"id":"B","text":"Sigilanții dentari."},{"id":"C","text":"Gelurile cu fluor."},{"id":"D","text":"Lacurile cu fluor de tip Bifluorid."},{"id":"E","text":"Apele de gură cu fluor."}],"correct":["C","E"],"pages":[383],"source":"set-2"},{"id":"set2-7uvT9Q6k","fingerprint":"01705bff4dc920e4","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Ce caracteristici prezintă gelurile cu fluor?","options":[{"id":"A","text":"Aderă la suprafețele dentare timp de câteva zile, eliberând lent fluorul."},{"id":"B","text":"Sunt indicate la copiii cu risc carios ridicat și la cei cu hiposalivație."},{"id":"C","text":"Sunt aplicate de obicei de două ori pe an în cabinetul stomatologic."},{"id":"D","text":"Sunt vehiculul ideal pentru aplicarea fluorului pe suprafețele dentare pentru toți copiii."},{"id":"E","text":"Majoritatea sunt ușor acide, florura fosfat acidulată (APF) îmbunătățind absorbția fluorului."}],"correct":["B","E"],"pages":[383],"source":"set-2"},{"id":"set2-HWi48EGV","fingerprint":"05869f59d3642e7f","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele reprezintă indicații pentru sigilarea șanțurilor și fosetelor?","options":[{"id":"A","text":"Dinți permanenți aflați în erupție, pentru a proteja smalțul imatur."},{"id":"B","text":"Tratamentul leziunilor carioase cavitare ocluzale."},{"id":"C","text":"Oprirea în evoluție a cariilor incipiente necavitare din șanțuri și fosete."},{"id":"D","text":"Prevenirea apariției cariilor din șanțuri și fosete."},{"id":"E","text":"Molari și premolari complet erupți la care se poate obține o izolare optimă."}],"correct":["C","D","E"],"pages":[383],"source":"set-2"},{"id":"set2-LNWQV_Jh","fingerprint":"c2e37762dceae591","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Ce este sigilarea dentară și care sunt mecanismele de aplicare ale materialului de sigilare?","options":[{"id":"A","text":"Un procedeu prin care un material este plasat în șanțuri și fosete pe baza adeziunii chimice, ca în cazul sigilanților pe bază de glassionomer."},{"id":"B","text":"O tehnică ce se bazează exclusiv pe adeziunea chimică, indiferent de materialul folosit."},{"id":"C","text":"Un tratament destinat exclusiv dinților temporari pentru a preveni cariile."},{"id":"D","text":"O metodă invazivă prin care se îndepărtează smalțul din șanțuri și se umple cu un material de obturație."},{"id":"E","text":"Un procedeu prin care un material este aplicat pe baza gravajului acid al suprafețelor dentare."}],"correct":["A","E"],"pages":[383],"source":"set-2"},{"id":"set2-7GboIBiK","fingerprint":"6ede8726ccbe5355","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Ce tipuri de materiale sunt utilizate în mod curent pentru sigilarea dentară?","options":[{"id":"A","text":"Amalgame dentare cu conținut redus de mercur."},{"id":"B","text":"Cimenturi cu zinc-oxid-eugenol modificate cu polimeri."},{"id":"C","text":"Glassionomeri cu priză chimică, fotoindusă sau mixtă."},{"id":"D","text":"Compomeri, definiți ca un amestec hibrid dintre glassionomeri și rășini compozite."},{"id":"E","text":"Rășini compozite, auto sau fotopolimerizabile, cu sau fără fluor."}],"correct":["C","D","E"],"pages":[384],"source":"set-2"},{"id":"set2-ptYeNZXn","fingerprint":"52b17c3b50919b07","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Care este motivul pentru care se utilizează o pastă de dinți fără fluor și glicerină în etapa de curățare a suprafeței dentare înainte de sigilare?","options":[{"id":"A","text":"Aceste substanțe pot provoca reacții alergice la contactul cu sigilantul."},{"id":"B","text":"Glicerina poate decolora sigilantul în timp, iar fluorul reduce timpul de priză."},{"id":"C","text":"Pasta cu fluor și glicerină este prea abrazivă pentru smalțul dinților tineri."},{"id":"D","text":"Ambele componente reduc aderența digăi la suprafața dentară."},{"id":"E","text":"Fluorul îngreunează gravarea smalțului, iar glicerina formează un strat impermeabil."}],"correct":["E"],"pages":[384],"source":"set-2"},{"id":"set2-PVF-DUDM","fingerprint":"1c82ce7e3c77b75e","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele afirmații referitoare la etapa de gravaj acid în tehnica de sigilare dentară sunt corecte?","options":[{"id":"A","text":"După aplicarea acidului, suprafața trebuie spălată abundent timp de 35-40 de secunde."},{"id":"B","text":"Timpul de acționare al acidului pe suprafața dentară este de 15-30 de secunde."},{"id":"C","text":"Se realizează cu acid orto-fosforic în concentrație de 35-37%."},{"id":"D","text":"Permite sigilantului să pătrundă aproximativ 50 μm în profunzimea smalțului."},{"id":"E","text":"Scopul său este îndepărtarea reziduurilor organice și crearea de microporozități."}],"correct":["B","C","D","E"],"pages":[384],"source":"set-2"},{"id":"set2-45HJOdjm","fingerprint":"04e1ac9f0b999b48","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Ce avantaj specific prezintă sigilanții colorați pe bază de rășini compozite?","options":[{"id":"A","text":"Necesită un timp de fotopolimerizare mai scurt datorită pigmenților."},{"id":"B","text":"Au o rezistență mecanică superioară sigilanților necolorați."},{"id":"C","text":"Sunt agreați de copii și permit o evaluare ușoară a remanenței și uzurii."},{"id":"D","text":"Au o vâscozitate mai redusă, permițând o penetrare mai bună în fosete."},{"id":"E","text":"Eliberează o cantitate mai mare de fluor pe o perioadă extinsă."}],"correct":["C"],"pages":[384],"source":"set-2"},{"id":"set2-bLqmHvmq","fingerprint":"cf2b44af2bbed468","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Ce reprezintă procedura de restaurare preventivă cu rășini (RPR)?","options":[{"id":"A","text":"O tehnică de albire internă a dinților cu leziuni carioase incipiente, urmată de sigilare."},{"id":"B","text":"O tehnică ce combină restaurarea cu sigilarea, având ca scop reducerea pierderii de substanță dură sănătoasă."},{"id":"C","text":"O procedură exclusiv de sigilare a dinților recent erupți, fără nicio leziune carioasă."},{"id":"D","text":"O metodă de restaurare care utilizează exclusiv cimenturi glassionomere."},{"id":"E","text":"Aplicarea unui material de restaurare doar în zonele afectate, fără a acoperi șanțurile și fosetele adiacente."}],"correct":["B"],"pages":[384],"source":"set-2"},{"id":"set2-5Cr9XrEl","fingerprint":"345916978fbe3eb2","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"În contextul restaurării preventive cu rășini, în ce situații clinice este preferată utilizarea cimenturilor glassionomer?","options":[{"id":"A","text":"În cazul leziunilor carioase foarte extinse, care afectează mai mulți cuspizi."},{"id":"B","text":"În cazul dinților nou erupți sau când izolarea este dificil de realizat."},{"id":"C","text":"Exclusiv la pacienții cu un risc carios scăzut, ca măsură de prevenție primară."},{"id":"D","text":"Când se dorește obținerea unei rezistențe maxime în timp și se poate realiza o izolare perfectă."},{"id":"E","text":"Când pacientul solicită o estetică deosebită a restaurării."}],"correct":["B"],"pages":[384],"source":"set-2"},{"id":"set2-SVS76vDJ","fingerprint":"63ab6034bdb7ac8e","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Conform tehnicii de sigilare, care este secvența corectă a pașilor după izolarea dintelui?","options":[{"id":"A","text":"Curățare cu pastă, gravaj acid, spălare și uscare, aplicare sigilant."},{"id":"B","text":"Spălare și uscare, gravaj acid, curățare cu pastă, aplicare sigilant."},{"id":"C","text":"Curățare cu pastă, aplicare adeziv, aplicare sigilant, gravaj acid."},{"id":"D","text":"Aplicare sigilant, fotopolimerizare, gravaj acid, verificare ocluzie."},{"id":"E","text":"Gravaj acid, curățare cu pastă, spălare și uscare, aplicare sigilant."}],"correct":["A"],"pages":[384],"source":"set-2"},{"id":"set2-wkcNR7-O","fingerprint":"8ae69511d3bede1f","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt caracteristicile definitorii ale cariei precoce a copilăriei (ECC) la grupa de vârstă 0-1 an?","options":[{"id":"A","text":"Afectează exclusiv molarii temporari."},{"id":"B","text":"Leziunile sunt de obicei oprite în evoluție în mod spontan."},{"id":"C","text":"Progresie extrem de rapidă."},{"id":"D","text":"Afectare pulpară frecventă în absența unui tratament adecvat."},{"id":"E","text":"Cooperarea copilului facilitează tratamentele restauratorii complexe."}],"correct":["C","D"],"pages":[385],"source":"set-2"},{"id":"set2-Z3W3JPvE","fingerprint":"47c2052c7a6f4e73","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"În gestionarea unui copil de 10 luni cu leziuni carioase severe și complicate, ce opțiuni de management comportamental farmacologic pot fi luate în considerare?","options":[{"id":"A","text":"Realizarea tratamentului fără nicio formă de sedare, pentru a crește cooperarea pe termen lung."},{"id":"B","text":"Amânarea oricărui tratament până la vârsta de 3 ani."},{"id":"C","text":"Anestezia generală."},{"id":"D","text":"Sedarea."},{"id":"E","text":"Limitarea strictă la tehnici non-operative."}],"correct":["C","D"],"pages":[385],"source":"set-2"},{"id":"set2-hC6m9nTC","fingerprint":"427724eca61ab54e","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Ce elemente sunt esențiale în strategia preventivă a cariei la copiii de 0-1 an, care implică direct instruirea părinților?","options":[{"id":"A","text":"Utilizarea unei paste de dinți cu fluor în cadrul unui program de periaj adecvat."},{"id":"B","text":"Întreruperea treptată a obiceiului de alimentare cu biberonul în timpul nopții."},{"id":"C","text":"Conștientizarea importanței îndepărtării plăcii bacteriene și a expunerii zilnice la fluor topic."},{"id":"D","text":"Inducerea unui sentiment de vină părinților pentru a-i motiva să schimbe obiceiurile."},{"id":"E","text":"Realizarea aplicațiilor profesionale de fluoruri la domiciliu de către părinți."}],"correct":["A","B","C"],"pages":[385],"source":"set-2"},{"id":"set2-Qm04T1X5","fingerprint":"dfd16fe57becb3a4","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Ce procedură specifică este recomandată pentru managementul leziunilor incipiente de pe incisivii unui copil din grupa de vârstă 0-1 an?","options":[{"id":"A","text":"O singură ședință de periaj profesional."},{"id":"B","text":"Realizarea unei restaurări preventive cu rășini."},{"id":"C","text":"Extracția dintelui pentru a preveni extinderea cariei."},{"id":"D","text":"Aplicarea unui strat subțire de lac fluorurat sau sigilant pe bază de ciment glassionomer."},{"id":"E","text":"Așteptarea erupției dinților permanenți înainte de orice intervenție."}],"correct":["D"],"pages":[385],"source":"set-2"},{"id":"set2-fAsknfKw","fingerprint":"2f5ebabd25bb6ccf","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt principalele caracteristici ale leziunilor carioase la grupa de vârstă 3-6 ani?","options":[{"id":"A","text":"Suprafețele cel mai des afectate la molarii temporari sunt cele vestibulare."},{"id":"B","text":"Leziunile carioase active la nivelul incisivilor temporari sunt mai puțin frecvente după vârsta de 3 ani."},{"id":"C","text":"Majoritatea leziunilor carioase la nivelul molarilor temporari la această vârstă depășesc smalțul și ajung în dentină."},{"id":"D","text":"Cariile proximale de pe molarii temporari nu influențează sănătatea molarilor permanenți."},{"id":"E","text":"În jurul vârstei de 5 ani, dinții cu cea mai mare experiență carioasă sunt molarii secunzi temporari."}],"correct":["B","E"],"pages":[385],"source":"set-2"},{"id":"set2-odXh_lzT","fingerprint":"d193e1818d9409c3","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Ce proceduri preventive sunt indicate pentru managementul leziunilor carioase la molarii temporari la copiii cu vârsta de aproximativ 5 ani?","options":[{"id":"A","text":"Sigilări."},{"id":"B","text":"Restaurări preventive cu rășini."},{"id":"C","text":"Aplicarea lunară de lacuri cu clorhexidină."},{"id":"D","text":"Extracții în serie pentru a crea spațiu."},{"id":"E","text":"Tratamente endodontice ca primă intenție."}],"correct":["A","B"],"pages":[385],"source":"set-2"},{"id":"set2-eGSOGadw","fingerprint":"c48b7b3c1e44b270","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt factorii care contribuie la vulnerabilitatea crescută a molarului prim permanent la procesele carioase în jurul vârstei de 6 ani?","options":[{"id":"A","text":"Faptul că erupe devreme și nu înlocuiește niciun alt dinte."},{"id":"B","text":"Particularitățile sale morfologice și structurale."},{"id":"C","text":"Necesitatea unui tratament exclusiv operativ imediat după erupție."},{"id":"D","text":"Poziția sa în arcadă și particularitățile de erupție."},{"id":"E","text":"Înlocuirea molarului secund temporar, un proces care slăbește structura smalțului."}],"correct":["A","B","D"],"pages":[386],"source":"set-2"},{"id":"set2-7A7adMjs","fingerprint":"66bec341367d12e6","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Ce strategie de tratament este recomandată pentru suprafața distală a molarului secund temporar care prezintă leziuni active, pentru a proteja suprafața mezială a molarului prim permanent?","options":[{"id":"A","text":"Restaurarea suprafeței cu amalgam, datorită durabilității crescute."},{"id":"B","text":"Aplicarea unui sigilant pe bază de rășini pentru a izola leziunea."},{"id":"C","text":"Monitorizarea leziunii și îmbunătățirea igienei orale, fără intervenție restauratoare."},{"id":"D","text":"Utilizarea cimentului glassionomer ca material de restaurare."},{"id":"E","text":"Aplicarea unui lac cu fluor pentru a remineraliza leziunea."}],"correct":["D"],"pages":[386],"source":"set-2"},{"id":"set2-7AjIZwnq","fingerprint":"86516b0b82666fde","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"La un copil de 5 ani, care sunt cele mai frecvent afectate suprafețe ale molarilor secunzi temporari și ce proceduri preventive sunt indicate pentru acestea?","options":[{"id":"A","text":"Doar suprafețele ocluzale; se indică transformarea leziunilor în leziuni inactive prin mijloace non-operative."},{"id":"B","text":"Doar suprafețele proximale; se indică exclusiv igiena alimentației și periajul."},{"id":"C","text":"Suprafețele vestibulare; se indică netezirea cu gume de finisat și aplicarea de lac fluorurat."},{"id":"D","text":"Suprafețele ocluzale; se indică exclusiv igiena alimentației și periajul."},{"id":"E","text":"Suprafețele ocluzale și proximale; se indică sigilări și restaurări preventive cu rășini."}],"correct":["E"],"pages":[386],"source":"set-2"},{"id":"set2-nqWQcVDX","fingerprint":"1c443b9e545fcabc","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Care este cea mai frecventă localizare a leziunilor carioase incipiente la grupa de vârstă 6-12 ani și ce măsuri preventive sunt indicate pentru aceasta?","options":[{"id":"A","text":"Suprafața distală a molarilor secunzi temporari; se indică restaurarea cu ciment glassionomer."},{"id":"B","text":"Suprafețele netede vestibulare; se indică aplicări topice de fluor."},{"id":"C","text":"Suprafețele proximale ale molarilor temporari; se indică tratament operativ."},{"id":"D","text":"Șanțurile și fosetele molarilor și premolarilor; se indică sigilarea preventivă și restaurarea preventivă cu rășini."},{"id":"E","text":"Coletul dinților frontali; se indică controlul plăcii bacteriene."}],"correct":["D"],"pages":[386],"source":"set-2"},{"id":"set2-9JLpBiIs","fingerprint":"3ad3a8d2bbcc51d7","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Care afirmație descrie corect prevalența și localizarea leziunilor carioase la vârsta de 13 ani?","options":[{"id":"A","text":"Majoritatea leziunilor carioase, circa 50%, afectează dinții frontali."},{"id":"B","text":"Aproximativ 80% dintre leziuni implică suprafețele proximale ale molarilor și premolarilor."},{"id":"C","text":"Suprafețele ocluzale sunt cele mai susceptibile la carie, reprezentând circa 60% din totalul leziunilor."},{"id":"D","text":"Suprafețele ocluzale ale molarilor și premolarilor sunt implicate în aproximativ 80% dintre leziuni."},{"id":"E","text":"Leziunile carioase sunt distribuite uniform pe toate suprafețele dentare la această vârstă."}],"correct":["D"],"pages":[386],"source":"set-2"},{"id":"set2-obnp1L5T","fingerprint":"3dfd9a885687b3aa","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Ce recomandări preventive sunt specificate pentru grupa de vârstă 12-19 ani?","options":[{"id":"A","text":"Utilizarea unei tehnici de periaj adecvate, precum tehnica Bass."},{"id":"B","text":"Restaurarea preventivă cu rășini a șanțurilor și fosetelor."},{"id":"C","text":"Periajul dentar o singură dată pe zi, dar cu o tehnică riguroasă."},{"id":"D","text":"Evitarea consumului frecvent de dulciuri și băuturi carbogazoase îndulcite."},{"id":"E","text":"Limitarea consumului de alimente de tip fast-food doar la sfârșit de săptămână."}],"correct":["A","B","D"],"pages":[386],"source":"set-2"},{"id":"set2-W8q6vB72","fingerprint":"dfaabb8fc03d7cdc","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele intervenții sunt considerate măsuri de prevenție specifice în cadrul nivelului de prevenție primară?","options":[{"id":"A","text":"Fluorizarea sistemului public de apă potabilă"},{"id":"B","text":"Tratamentul prompt al cariilor incipiente prin restaurări preventive cu rășini"},{"id":"C","text":"Ortodonția interceptivă pentru corectarea obiceiurilor vicioase"},{"id":"D","text":"Aplicațiile topice de fluor"},{"id":"E","text":"Profilaxia dentară profesională"}],"correct":["A","D","E"],"pages":[378],"source":"set-2"},{"id":"set2-GPc7k49q","fingerprint":"d38f5845f6bea6a0","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Ce acțiuni clinice și diagnostice sunt specifice prevenției secundare a afecțiunilor oro-dentare?","options":[{"id":"A","text":"Monitorizarea anomaliilor de dezvoltare dentară"},{"id":"B","text":"Utilizarea radiografiilor pentru detectarea leziunilor carioase incipiente"},{"id":"C","text":"Promovarea sănătății prin educația oro-dentară a populației"},{"id":"D","text":"Înlocuirea structurilor dentare pierdute prin lucrări protetice"},{"id":"E","text":"Extensia preventivă pentru prevenirea apariției leziunilor carioase secundare"}],"correct":["A","B","E"],"pages":[379],"source":"set-2"},{"id":"set2-MiFI6nhW","fingerprint":"0ecb11ee18cd7938","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la măsurile caracteristice nivelului de prevenție terțiară?","options":[{"id":"A","text":"Optează pentru extensia preventivă în scopul prevenirii leziunilor carioase secundare"},{"id":"B","text":"Vizează reducerea sau limitarea tulburărilor deja instalate și minimizarea suferințelor"},{"id":"C","text":"Include tratamentul curativ al afecțiunilor asociat cu o abordare preventivă pentru evitarea complicațiilor"},{"id":"D","text":"Cuprinde intervenții precum coafajul pulpar și terapia endodontică"},{"id":"E","text":"Implică screening-ul periodic pentru diagnosticarea precoce a leziunilor incipiente"}],"correct":["B","C","D"],"pages":[379],"source":"set-2"},{"id":"set2-Oqdb0SiG","fingerprint":"0d5e789464b92aca","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele proceduri sunt incluse în categoria îngrijirii profesionale, conform conceptelor stomatologiei preventive?","options":[{"id":"A","text":"Restaurările preventive cu rășini (RPR)"},{"id":"B","text":"Folosirea aței dentare"},{"id":"C","text":"Periajul dentar"},{"id":"D","text":"Sigilarea șanțurilor și a fosetelor"},{"id":"E","text":"Terapia cu fluor"}],"correct":["A","D","E"],"pages":[379],"source":"set-2"},{"id":"set2-WvDFRVuK","fingerprint":"0f1e709ed7ba7578","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"În ce stadiu de evoluție al unei afecțiuni oro-dentare este indicată aplicarea măsurilor de prevenție secundară?","options":[{"id":"A","text":"În perioada prepatogenă, înainte de debutul manifestărilor clinice"},{"id":"B","text":"În etapa de reabilitare orală a pacienților cu pierderi structurale majore"},{"id":"C","text":"În perioada de debut, prin diagnostic precoce și tratament imediat"},{"id":"D","text":"După instalarea complicațiilor severe, pentru limitarea suferințelor"},{"id":"E","text":"În momentul inițierii igienei nutriționale pentru reducerea riscului carios"}],"correct":["C"],"pages":[378],"source":"set-2"},{"id":"set2-kSJnPbgh","fingerprint":"8f377ad0a6aac9f7","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt caracteristicile tehnicii de periaj Bass?","options":[{"id":"A","text":"Este recomandată pacienților cu o dexteritate bună, fiind indicată în a doua etapă a dentiției mixte și în dentația permanentă."},{"id":"B","text":"Asigură protecția caninului prin igienizarea jumătății sale meziale concomitent cu dinții din zona laterală."},{"id":"C","text":"Presupune așezarea periuței într-un unghi de 45° față de axul lung al dinților, cu perii orientați spre sulcusul gingival."},{"id":"D","text":"Implică perierea simultană a arcadelor dentare menținute în contact strâns."},{"id":"E","text":"Este indicată copiilor de până în 6-8 ani, aflați în stadiul de dentație temporară sau la începutul dentiției mixte."}],"correct":["A","C"],"pages":[380],"source":"set-2"},{"id":"set2-zXJsfmtw","fingerprint":"3877f5d8e902c2aa","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt principiile și recomandările esențiale pentru un periaj dentar corect la pacienții pediatrici?","options":[{"id":"A","text":"Părinții au responsabilitatea de a efectua periajul dentar al copilului cel puțin până la vârsta de 6 ani."},{"id":"B","text":"Periajul de seară este considerat cel mai important din cauza absenței autocurățirii salivare pe parcursul nopții."},{"id":"C","text":"Periuța de dinți manuală cu peri moi trebuie înlocuită standard la un interval de 6 luni."},{"id":"D","text":"Cantitatea de pastă de dinți fluorurată necesară pentru copiii cu vârsta între 0 și 3 ani este echivalentă cu un bob de mazăre."},{"id":"E","text":"Obiceiul de periaj propriu-zis trebuie însușit de către copil odată cu erupția primului dinte temporar."}],"correct":["A","B"],"pages":[380],"source":"set-2"},{"id":"set2-CRX5RMqz","fingerprint":"95b987754b898937","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la utilizarea agenților antibacterieni în igiena orală a copiilor?","options":[{"id":"A","text":"Clorhexidina prezintă o afinitate puternică pentru microorganismele Gram-pozitive, însă afectează în mai mică măsură lactobacilii."},{"id":"B","text":"Clătirile cu soluție de clorhexidină 0,2% substituie complet necesitatea periajului dentar la copiii compromiși din punct de vedere medical."},{"id":"C","text":"Administrarea combinată a fluorului și clorhexidinei prelungește timpul de suprimare a bacteriei Streptococcus mutans."},{"id":"D","text":"Periajul dentar trebuie realizat imediat după aplicarea clorhexidinei pentru a maximiza efectul bactericid asupra plăcii bacteriene."},{"id":"E","text":"Clătirile orale cu clorhexidină sunt contraindicate copiilor sub 6 ani din cauza riscului de ingestie accidentală."}],"correct":["A","C","E"],"pages":[381],"source":"set-2"},{"id":"set2-dW-p7DkG","fingerprint":"4569db6a923eb984","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următorii factori și indicatori fac parte din strategia de evaluare a riscului carios și de igienă nutrițională?","options":[{"id":"A","text":"Evaluarea riscului carios se realizează într-o etapă singulară pentru trasarea unui plan definitiv de prevenție."},{"id":"B","text":"Obiectivele evaluării includ stabilirea intervalului de reevaluare a pacientului și detectarea subiecților cu susceptibilitate crescută."},{"id":"C","text":"Raportul dintre anumiți agenți patologici specifici și factorii de protecție determină echilibrul dintre dezvoltarea, oprirea în evoluție sau reversibilitatea bolii carioase."},{"id":"D","text":"Se recomandă consumul alimentelor cu o consistență dură, care nu aderă de suprafețele dentare și favorizează autocurățirea."},{"id":"E","text":"Controlul aportului de zaharoză presupune favorizarea alimentelor moi, lipicioase, care asigură o peliculă protectoare pe termen lung."}],"correct":["B","C","D"],"pages":[379],"source":"set-2"},{"id":"set2-yYeQYzws","fingerprint":"d10403f03e47cd8c","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Care dintre următoarele afirmații descrie corect tehnica de periaj Fones?","options":[{"id":"A","text":"Asigură o igienizare optimă a șanțului gingival prin pătrunderea selectivă a perilor la acest nivel."},{"id":"B","text":"Periuța este orientată la un unghi de 45 de grade față de axul lung al dinților."},{"id":"C","text":"Presupune menținerea arcadelor dentare în contact și realizarea unor mișcări rotative cu rază largă."},{"id":"D","text":"Necesită realizarea unor mișcări scurte, de tip circular-vibrator, pentru fiecare zonă dentară periată."},{"id":"E","text":"Este considerată tehnica de primă intenție pentru copiii aflați în a doua etapă a dentiției mixte."}],"correct":["C"],"pages":[380],"source":"set-2"},{"id":"set2-ChElBiLM","fingerprint":"52f3dbabe8a35db8","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Un copil se prezintă la cabinetul de medicină dentară prezentând la nivelul smalțului dinților permanenți zone opace, cretoase, alb-gălbui, neregulate, care acoperă aproximativ 10-25% din suprafața dentară. La nivelul molarilor se observă un lizereu albicios de 1-2 mm, iar marginile incizale ale incisivilor și vârfurile cuspidiene ale caninilor sunt afectate. Care este stadiul fluorozei dentare în această situație clinică?","options":[{"id":"A","text":"Fluoroză incertă (stadiul I)"},{"id":"B","text":"Fluoroză ușoară (stadiul III)"},{"id":"C","text":"Fluoroză foarte ușoară (stadiul II)"},{"id":"D","text":"Fluoroză severă (stadiul V)"},{"id":"E","text":"Fluoroză moderată (stadiul IV)"}],"correct":["C"],"pages":[382],"source":"set-2"},{"id":"set2-dquYsNZL","fingerprint":"f191a0bec1c4a6ce","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt afirmațiile adevărate privind toxicitatea fluorului și dezvoltarea fluorozei dentare?","options":[{"id":"A","text":"Doza prag pentru dezvoltarea fluorozei ușoare la nivelul dinților permanenți este estimată la 40-100 µg F/kg/zi."},{"id":"B","text":"Doza de fluor care depășește 15 mg/kg este considerată letală."},{"id":"C","text":"Utilizarea corectă a pastelor de dinți cu fluor reprezintă un factor de risc major pentru apariția fluorozei dentare."},{"id":"D","text":"Aplicările topice profesionale de fluor determină frecvent dezvoltarea defectelor calitative ale smalțului."},{"id":"E","text":"Doza toxică acută apare la ingerarea unei cantități de 5 mg F/kg și se manifestă prin greață, vărsături, parestezii sau convulsii."}],"correct":["A","B","E"],"pages":[382],"source":"set-2"},{"id":"set2-WmsY7l20","fingerprint":"dec4156160db2fb8","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Privind administrarea și dozarea produselor pe bază de fluor în perioada de creștere, care dintre următoarele corelații referitoare la cantitatea de pastă de dinți recomandată sunt exacte?","options":[{"id":"A","text":"După vârsta de 3 ani, cantitatea de pastă de dinți recomandată trebuie să fie de dimensiunea unui bob de orez."},{"id":"B","text":"Între 6 luni și 3 ani, cantitatea de pastă de dinți trebuie să fie de dimensiunea unui bob de mazăre."},{"id":"C","text":"De la vârsta de 5-6 ani, cantitatea de pastă de dinți poate acoperi jumătate din capul periuței."},{"id":"D","text":"Utilizarea pastelor de dinți cu fluor se inițiază exclusiv după erupția completă a dentiției permanente."},{"id":"E","text":"Copiii mici înghit în general aproximativ 50% din cantitatea de pastă de dinți utilizată la periaj."}],"correct":["C"],"pages":[383],"source":"set-2"},{"id":"set2-Qtj6DpKV","fingerprint":"9b6ef6ec8bce3f37","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt mecanismele prin care fluorul intervine în prevenirea apariției leziunilor carioase?","options":[{"id":"A","text":"Cristalele de fluorură de calciu acționează ca un sistem cu eliberare lentă a fluorurii controlat de pH, fiind dizolvate atunci când pH-ul scade."},{"id":"B","text":"Prezența fluorului în fluidul din placa bacteriană în timpul provocării acide încetinește dizolvarea smalțului și susține faza de precipitare."},{"id":"C","text":"Încorporarea fluorului în cristalele de hidroxiapatită în timpul mineralizării generează o rezistență permanentă a smalțului, reprezentând principalul mecanism anticariogen actual."},{"id":"D","text":"Eficiența maximă anticariogenă implică prezența fluorului exclusiv în profunzimea stratului de dentină subiacentă smalțului."},{"id":"E","text":"Aplicarea topică a fluorului determină formarea unor cristale de fluorură de calciu care se acumulează pe suprafața dentară."}],"correct":["A","B","E"],"pages":[381],"source":"set-2"},{"id":"set2-cTCC9nhJ","fingerprint":"3cf47985bd54114e","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Referitor la produsele pe bază de fluor utilizate în aplicările topice, care dintre următoarele afirmații sunt exacte?","options":[{"id":"A","text":"Gelurile cu fluor sunt indicate în special la copiii cu risc carios ridicat și la cei cu hiposalivație."},{"id":"B","text":"Apele de gură și gelurile cu fluor sunt recomandate cu predilecție copiilor de vârstă preșcolară pentru o eficiență sporită."},{"id":"C","text":"Lacurile cu fluor conțin concentrații mari de fluor, aderă la suprafața dentară câteva zile și se recomandă a fi aplicate o singură dată la doi ani."},{"id":"D","text":"Fluorura fosfat acidulată (APF) prezentă în gelurile cu fluor îmbunătățește absorbția fluorului pe suprafața smalțului."},{"id":"E","text":"Clătirea zilnică cu soluție de fluorură de sodiu (NaF) 0,05% este considerată cea mai eficientă metodă de utilizare a apelor de gură cu fluor, scăzând leziunile carioase cu 20-40%."}],"correct":["A","D","E"],"pages":[383],"source":"set-2"},{"id":"set2-xjg48Jqx","fingerprint":"0f66ff8c29cd792f","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele aspecte clinice reprezintă indicații pentru realizarea sigilării șanțurilor și fosetelor?","options":[{"id":"A","text":"Aplicarea la dinții temporari sau permanenți aflați în erupție la care nu se poate asigura o izolare adecvată."},{"id":"B","text":"Oprirea în evoluție a cariilor incipiente necavitare din șanțuri și fosete."},{"id":"C","text":"Aplicarea la molarii și premolarii complet erupți la care se poate obține o izolare optimă."},{"id":"D","text":"Cariile incipiente prezente la nivelul dinților nou erupți."},{"id":"E","text":"Prevenirea leziunilor carioase pe suprafețele dentare radiculare expuse în urma recesiunilor parodontale."}],"correct":["B","C","D"],"pages":[383],"source":"set-2"},{"id":"set2-rabquLOX","fingerprint":"787a26d55d95078c","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Ce caracteristici descriu corect etapele de curățare și gravaj acid în tehnica sigilării dentare?","options":[{"id":"A","text":"Etapa de gravaj permite pătrunderea sigilantului la aproximativ 50 μm în profunzimea stratului de smalț."},{"id":"B","text":"Pasta utilizată pentru periaj nu trebuie să conțină fluor, deoarece acesta face dificilă gravarea smalțului."},{"id":"C","text":"Gravajul acid se realizează cu acid orto-fosforic în concentrație de 35-37%."},{"id":"D","text":"Este obligatorie includerea glicerinei în pasta de curățare pentru a crea un strat de protecție la suprafața smalțului."},{"id":"E","text":"Acidul orto-fosforic este lăsat să acționeze timp de 10-15 secunde, urmat imediat de spălare timp de 15-30 secunde."}],"correct":["A","B","C"],"pages":[383],"source":"set-2"},{"id":"set2-ALgMZ5HY","fingerprint":"e6f529133786a725","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Care este efectul aplicării unei paste ce conține glicerină în timpul etapei de curățare a suprafeței dentare?","options":[{"id":"A","text":"Realizează microporozități specifice prin care monomerul poate pătrunde în structura dentară."},{"id":"B","text":"Crește profunzimea de penetrare a sigilantului la aproximativ 50 μm în stratul de smalț."},{"id":"C","text":"Asigură o bază de fixare prin adeziune chimică directă pentru materialele glassionomere."},{"id":"D","text":"Formează un strat impermeabil pe suprafața dentară."},{"id":"E","text":"Facilitează disoluția și îndepărtarea reziduurilor organice de la nivelul fisurilor."}],"correct":["D"],"pages":[383],"source":"set-2"},{"id":"set2-fUkSb-fH","fingerprint":"ba563427f6570669","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care sunt procedurile corecte privind etapa de aplicare a sigilantului și adaptarea clinică a acestuia?","options":[{"id":"A","text":"Sigilantul se aplică strict în profunzimea șanțurilor, evitându-se prelingerea pe versanții cuspidieni adiacenți."},{"id":"B","text":"Reevaluarea rezultatului clinic se efectuează în mod standard la un interval de 12 luni de la aplicare."},{"id":"C","text":"Înaintea aplicării sigilantului propriu-zis se poate utiliza un strat de adeziv."},{"id":"D","text":"Se recomandă așteptarea timp de 10 secunde înaintea fotopolimerizării pentru penetrarea optimă a sigilantului pe suprafața gravată."},{"id":"E","text":"Adaptarea funcțională presupune verificarea ocluziei cu hârtie de articulație și îndepărtarea contactelor patologice."}],"correct":["C","D","E"],"pages":[383],"source":"set-2"},{"id":"set2-IR7wuFmi","fingerprint":"04a03cae709f098c","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Ce caracteristici descriu materialele destinate utilizării în sigilarea dentară?","options":[{"id":"A","text":"Rășinile posedă o capacitate demonstrată de a opri progresia leziunilor carioase inclusiv la nivelul dentinei."},{"id":"B","text":"Glassionomerii asigură fixarea structurală prin intermediul adeziunii chimice a materialului la dinte."},{"id":"C","text":"Compomerii reprezintă materiale constituite dintr-un amestec hibrid alcătuit din glassionomeri și rășini compozite."},{"id":"D","text":"Rășinile compozite trebuie să conțină obligatoriu fluor pentru a avea un rol profilactic."},{"id":"E","text":"Sigilanții colorați pe bază de rășini compozite facilitează detectarea remanenței materialului pe dinte, a uzurii și a necesității reaplicării."}],"correct":["A","B","C","E"],"pages":[383],"source":"set-2"},{"id":"set2-T1Vj7Zlw","fingerprint":"6c93cdd5c6d0ca1b","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Care dintre următoarele afirmații descriu adecvat principiile de selecție și aplicare a materialelor pentru restaurarea preventivă cu rășini la nivelul șanțurilor și fosetelor?","options":[{"id":"A","text":"Cimenturile glassionomere sunt indicate de primă intenție în cazul dinților nou erupți sau atunci când izolarea este dificilă."},{"id":"B","text":"Compomerii reprezintă materiale total contraindicate în procedura minim invazivă de restaurare preventivă."},{"id":"C","text":"Rășinile compozite sunt evitate în condițiile obținerii unei izolări adecvate din cauza rezistenței lor scăzute în timp."},{"id":"D","text":"Sigilanții pe bază de rășini compozite sunt preferați în situațiile cu izolare optimă datorită durabilității și rezistenței crescute în timp."},{"id":"E","text":"Procedura presupune îndepărtarea țesuturilor dentare alterate de la nivelul zonelor afectate, urmată de aplicarea materialului care va acoperi și restul șanțurilor și fosetelor."}],"correct":["A","D","E"],"pages":[386],"source":"set-2"},{"id":"set2-7JPi9Xu0","fingerprint":"82e5709c636d4d85","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Conduita terapeutică adecvată pentru leziunile carioase incipiente localizate la nivelul incisivilor, la pacienții din grupa de vârstă 0-1 an, implică:","options":[{"id":"A","text":"Îndepărtarea prealabilă a plăcii bacteriene și a țesuturilor moi cu ajutorul unei periuțe, urmată de netezirea suprafețelor cu gume de finisat."},{"id":"B","text":"Aplicarea unui strat subțire de lac fluorurat sau a unui sigilant pe bază de ciment glassionomer la nivelul zonei afectate."},{"id":"C","text":"Repetarea procedurii de aplicare în mod frecvent, de regulă o dată pe lună, până la oprirea în evoluție a leziunii."},{"id":"D","text":"Repetarea procedurilor de aplicare topică a agenților de remineralizare exclusiv o dată la șase luni pentru a evita supradozajul."},{"id":"E","text":"Instituirea imediată a tehnicilor operative radicale pentru a preîntâmpina afectarea timpurie a pulpei dentare."}],"correct":["A","B","C"],"pages":[386],"source":"set-2"},{"id":"set2-f7ZwsJu8","fingerprint":"45ea9c3afa525c5b","chapterId":"set-2","subchapterId":"set2-5.02","type":"CS","text":"Pentru prevenția cariilor la nivelul suprafeței meziale a molarului prim permanent (grupa de vârstă 6-12 ani), care este materialul de elecție utilizat în tratamentul suprafeței distale a molarului secund temporar afectat de leziuni active?","options":[{"id":"A","text":"Amalgamul de argint, datorită rezistenței sale mecanice deosebite la forțele masticatorii."},{"id":"B","text":"Rășina compozită fluidă, pentru o adaptare marginală superioară în cavitățile cu retentivitate redusă."},{"id":"C","text":"Compomerul fotopolimerizabil, grație esteticii ridicate și a timpului redus de prelucrare clinică."},{"id":"D","text":"Cimentul glassionomer, datorită potențialului cario-preventiv prin eliberarea de fluor."},{"id":"E","text":"Cimentul silicat, utilizat pentru efectul său puternic antimicrobian local."}],"correct":["D"],"pages":[386],"source":"set-2"},{"id":"set2-1yr5LRlM","fingerprint":"7d3de2fb2f6985e3","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Analizând evoluția, prevalența și topografia leziunilor carioase pe grupe de vârstă, care dintre următoarele caracteristici sunt corecte?","options":[{"id":"A","text":"La vârsta de 13 ani, aproximativ 80% dintre leziunile carioase tratate sau netratate implică suprafețele ocluzale ale molarilor și premolarilor."},{"id":"B","text":"La grupa de vârstă 3-6 ani, majoritatea leziunilor carioase de la nivelul molarilor temporari prezintă o extindere profundă și progresivă în dentină."},{"id":"C","text":"După depășirea vârstei de 3 ani, incidența leziunilor carioase active la nivelul incisivilor temporari înregistrează o creștere semnificativă."},{"id":"D","text":"În jurul vârstei de 5 ani, dinții care prezintă cea mai mare experiență carioasă sunt molarii secunzi temporari."},{"id":"E","text":"La pacienții din grupa de vârstă 6-12 ani, se observă o creștere substanțială a leziunilor carioase la nivelul suprafețelor proximale ale molarilor temporari."}],"correct":["A","D","E"],"pages":[386],"source":"set-2"},{"id":"set2-T4XDExoW","fingerprint":"1fc36fe69e8a5d44","chapterId":"set-2","subchapterId":"set2-5.02","type":"CM","text":"Caria precoce a copilăriei (ECC) prezintă o serie de trăsături evolutive și recomandări terapeutice specifice grupei de vârstă 0-1 an. Care dintre următoarele afirmații sunt corecte în legătură cu managementul clinic al acestei afecțiuni?","options":[{"id":"A","text":"Progresia leziunii este extrem de rapidă, conducând în scurt timp la afectare pulpară în absența unui tratament adecvat."},{"id":"B","text":"Tehnicile operative extinse reprezintă standardul de aur și trebuie aplicate prioritar pentru a stopa complicațiile pulpare timpurii."},{"id":"C","text":"Obiceiul alimentării cu biberonul în timpul nopții constituie un factor etiologic major ce impune întreruperea sa bruscă și definitivă încă de la prima vizită."},{"id":"D","text":"Principalul deziderat al terapiei este de natură non-operativă, urmărind transformarea leziunilor active în leziuni inactive sau oprite în evoluție."},{"id":"E","text":"Se recomandă recurgerea la metode de management comportamental farmacologic, precum sedarea sau anestezia generală, în cazurile severe cu leziuni complicate."}],"correct":["A","D","E"],"pages":[386],"source":"set-2"}];
